// Ymatch — Over ons (About) page.
//
// Sections: Hero · Het verhaal · Drie kernwaarden · Missie/Visie/BHAG
//          · Het team · In cijfers · Werk bij Ymatch · Kantoor
//
// Content rewritten with real Ymatch copy (june 2026): the founder story
// (DirkJan, 23, zolder van het familiebedrijf → Krimpen → Capelle 2021)
// and the three kernwaarden (Vuur · Puur · Vakmanschap) plus the
// Missie/Visie/BHAG from the brand kaartjes.

// ── Helpers ──
function Eyebrow({ children, onDark = false }) {
  return (
    <span style={{ fontFamily: "var(--font-mono)", fontSize: "11px", fontWeight: 700, letterSpacing: ".08em", textTransform: "uppercase", color: onDark ? "var(--orange)" : "var(--orange)", display: "inline-block" }}>
      {children}
    </span>
  );
}

function Wrap({ id, children, top = 120, bottom = 0 }) {
  const isMobile = window.useIsMobile();
  return (
    <section id={id} style={{
      maxWidth: "1200px", margin: "0 auto",
      padding: `${isMobile ? Math.round(top * 0.6) : top}px ${isMobile ? 20 : 40}px ${isMobile ? Math.round(bottom * 0.7) : bottom}px`,
    }}>{children}</section>
  );
}

// ── 1. Hero — "Wij zijn geen cv-fabriek." ──
function HeroAbout() {
  const isMobile = window.useIsMobile();
  return (
    <section style={{ position: "relative", padding: isMobile ? "32px 20px 56px" : "56px 40px 80px" }}>
      <div style={{ maxWidth: "1200px", margin: "0 auto" }}>
        <div style={{ display: "flex", alignItems: "center", gap: "14px", marginBottom: "20px", flexWrap: "wrap", fontFamily: "var(--font-mono)", fontSize: "11px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase" }}>
          <span style={{ color: "var(--orange)" }}>Wie zijn wij</span>
          <span style={{ color: "var(--subtle)" }}>·</span>
          <span style={{ color: "var(--muted)" }}>Zolder → Krimpen → Capelle a/d IJssel</span>
          <span style={{ color: "var(--subtle)" }}>·</span>
          <span style={{ color: "var(--muted)" }}>15 op kantoor</span>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1.2fr 1fr", gap: isMobile ? "32px" : "64px", alignItems: "center" }}>
          <div>
            <h1 style={{
              fontFamily: "var(--font-display)", fontWeight: 800,
              fontSize: isMobile ? "clamp(46px, 11vw, 64px)" : "clamp(60px, 7vw, 96px)",
              letterSpacing: "-.05em", lineHeight: ".92",
              color: "var(--ink)", margin: 0, textWrap: "balance",
            }}>
              Wij zijn geen<br/><em style={{ fontStyle: "italic", fontWeight: 300 }}>cv-fabriek</em>.
            </h1>
            <p style={{ fontFamily: "var(--font-hand)", fontSize: "28px", color: "var(--orange)", margin: "20px 0 0", lineHeight: 1.1, transform: "rotate(-1.5deg)", transformOrigin: "left" }}>
              Wij zijn vijftien mensen.
            </p>
            <p style={{ fontFamily: "var(--font-display)", fontSize: isMobile ? "17px" : "19px", lineHeight: 1.55, color: "var(--muted)", margin: "24px 0 0", maxWidth: "560px" }}>
              We zijn een onafhankelijk recruitment- en detacheringsbureau. Vijftien
              mensen die graag <b style={{ color: "var(--ink)" }}>met hun voeten in de klei staan</b>,
              het werk van hun kandidaten begrijpen, en geloven dat een goede match
              begint met een goed gesprek.
            </p>
            <p style={{ fontFamily: "var(--font-display)", fontSize: isMobile ? "16px" : "17px", lineHeight: 1.55, color: "var(--muted)", margin: "16px 0 0", maxWidth: "560px" }}>
              We schrijven geen vacatures vol met buzzwords. We bellen je op,
              luisteren goed, en zoeken pas <b style={{ color: "var(--ink)" }}>dán</b> de juiste plek.
            </p>
          </div>

          {!isMobile && (
            <div style={{ position: "relative" }}>
              <div aria-hidden="true" style={{ position: "absolute", top: "-30px", right: "-30px", width: "220px", height: "220px", borderRadius: "50%", border: "1.5px solid var(--orange)", opacity: .16, pointerEvents: "none" }} />
              <div aria-hidden="true" style={{ position: "absolute", bottom: "-20px", left: "-30px", width: "160px", height: "160px", borderRadius: "50%", background: "var(--orange)", opacity: .08, pointerEvents: "none" }} />
              <div style={{
                position: "relative",
                background: "var(--card)", borderRadius: "var(--r-lg)",
                border: "1px solid var(--line)", boxShadow: "var(--shadow-lg)",
                overflow: "hidden",
              }}>
                <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: "4px", background: "var(--orange)", zIndex: 2 }} />
                <img
                  src="data:image/jpeg;base64,"
                  alt="Het Ymatch-team"
                  style={{ display: "block", width: "100%", height: "520px", objectFit: "cover", objectPosition: "center 50%" }} />
              </div>
              <div style={{
                position: "absolute", bottom: "-20px", right: "-12px", zIndex: 3,
                background: "var(--ink)", color: "#fff", padding: "14px 18px",
                borderRadius: "var(--r)", boxShadow: "var(--shadow-lg)",
                transform: "rotate(1.5deg)", textAlign: "right",
              }}>
                <div style={{ fontFamily: "var(--font-display)", fontWeight: 800, fontSize: "26px", lineHeight: 1, letterSpacing: "-.03em" }}>
                  1.000<span style={{ color: "var(--orange)" }}>+</span>
                </div>
                <div style={{ fontFamily: "var(--font-mono)", fontSize: "9px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "rgba(255,255,255,.6)", marginTop: "4px" }}>
                  bemiddelingen
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

// ── 2. Het verhaal — DirkJan's story ──
function HetVerhaal() {
  const isMobile = window.useIsMobile();
  const stappen = [
    { jaar: "2010", plek: "Zolder",   waar: "Familiebedrijf · vader",      n: "01" },
    { jaar: "2014", plek: "Krimpen",  waar: "Eerste eigen pand",            n: "02" },
    { jaar: "2021", plek: "Capelle",  waar: "Hoofdweg 100 · 15 collega's",  n: "03" },
  ];
  return (
    <Wrap top={88}>
      <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1.2fr", gap: isMobile ? "32px" : "72px", alignItems: "flex-start" }}>
        <div style={{ position: "relative" }}>
          {!isMobile && (
            <div aria-hidden="true" style={{ position: "absolute", top: "-24px", right: "-24px", width: "140px", height: "140px", borderRadius: "50%", border: "1.5px solid var(--blue)", opacity: .14, pointerEvents: "none" }} />
          )}
          <figure style={{
            margin: 0, position: "relative",
            background: "var(--card)", borderRadius: "var(--r-lg)",
            border: "1px solid var(--line)", boxShadow: "var(--shadow-sm)", overflow: "hidden",
          }}>
            <img src="data:image/jpeg;base64," alt="Kantoor Ymatch in Capelle aan den IJssel"
              style={{ display: "block", width: "100%", height: isMobile ? "300px" : "520px", objectFit: "cover" }} />
            <figcaption style={{
              position: "absolute", bottom: "16px", left: "16px",
              background: "rgba(21,23,28,.85)", color: "#fff",
              fontFamily: "var(--font-mono)", fontSize: "10px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase",
              padding: "6px 10px", borderRadius: "var(--r-xs)",
            }}>
              Hoofdweg 100 · Capelle a/d IJssel
            </figcaption>
          </figure>

          {/* Timeline strip under the photo */}
          <div style={{ marginTop: "16px", display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: "8px" }}>
            {stappen.map((s) => (
              <div key={s.n} style={{ background: "var(--card)", border: "1px solid var(--line)", borderRadius: "var(--r-sm)", padding: "12px 14px", position: "relative" }}>
                <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: "2px", background: "var(--orange)" }} />
                <div style={{ fontFamily: "var(--font-mono)", fontSize: "10px", fontWeight: 700, letterSpacing: ".06em", color: "var(--orange)" }}>{s.n} · {s.jaar}</div>
                <div style={{ fontFamily: "var(--font-display)", fontWeight: 800, fontSize: "16px", letterSpacing: "-.02em", margin: "4px 0 2px" }}>{s.plek}</div>
                <div style={{ fontSize: "11px", color: "var(--muted)" }}>{s.waar}</div>
              </div>
            ))}
          </div>
        </div>

        <div>
          <div style={{ marginBottom: "16px" }}><Eyebrow>Het verhaal</Eyebrow></div>
          <h2 style={{
            fontFamily: "var(--font-display)", fontWeight: 800,
            fontSize: isMobile ? "clamp(32px, 8vw, 44px)" : "clamp(40px, 4.8vw, 60px)",
            letterSpacing: "-.045em", lineHeight: ".98",
            color: "var(--ink)", margin: "0 0 24px", textWrap: "balance",
          }}>
            Begonnen op een <em style={{ fontStyle: "italic", fontWeight: 300 }}>zolder</em>. Op zijn 23ste.
          </h2>
          <div style={{ display: "flex", flexDirection: "column", gap: "18px", fontFamily: "var(--font-display)", fontSize: isMobile ? "16px" : "18px", lineHeight: 1.65, color: "var(--ink)", maxWidth: "560px" }}>
            <p style={{ margin: 0 }}>
              <b>DirkJan Kalkman</b> was 23 toen hij Ymatch oprichtte. Hij werkte
              zelf in de techniek en wist hoe het er aan de andere kant aan toeging
              — werkgevers die niet precies wisten wat ze zochten, vakmensen die
              geen idee hadden of een vacature klopte. Daar moest het persoonlijker
              kunnen.
            </p>
            <p style={{ margin: 0 }}>
              Hij begon op zolder, bij het familiebedrijf van zijn vader. Eén
              telefoon, een Excel-sheet en zijn eigen netwerk in de techniek.
              Toen het te krap werd: een eigen pand in <b>Krimpen aan den IJssel</b>.
              En sinds <b>2021</b> aan de Hoofdweg in <b>Capelle</b>, met inmiddels
              vijftien mensen op kantoor.
            </p>
            <p style={{ margin: 0 }}>
              Niet meer alleen techniek — ook bouw en office. Niet meer in z'n
              eentje — maar wel nog steeds met dezelfde manier van werken. Bellen,
              luisteren, en pas dan een vacature in iemand zijn schoot duwen. Geen
              massa, wel maatwerk.
            </p>
          </div>

          {/* DirkJan quote */}
          <div style={{
            marginTop: "32px", padding: "20px 24px", display: "flex", gap: "16px", alignItems: "center",
            background: "var(--bg-2)", borderRadius: "var(--r)", borderLeft: "3px solid var(--orange)",
          }}>
            <div style={{ flexShrink: 0, width: "48px", height: "48px", borderRadius: "50%", background: "var(--ink)", color: "#fff", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: "var(--font-hand)", fontWeight: 700, fontSize: "20px" }}>DK</div>
            <div>
              <p style={{ fontFamily: "var(--font-hand)", fontSize: "22px", color: "var(--ink)", margin: 0, lineHeight: 1.2, transform: "rotate(-.5deg)", transformOrigin: "left" }}>
                "Ik wil iemand pas voorstellen als ik 'm zelf zou aannemen."
              </p>
              <div style={{ fontFamily: "var(--font-mono)", fontSize: "10px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: "var(--muted)", marginTop: "8px" }}>
                DirkJan Kalkman · oprichter
              </div>
            </div>
          </div>
        </div>
      </div>
    </Wrap>
  );
}

// ── 3. Drie kernwaarden — Vuur · Puur · Vakmanschap ──
function DrieKernwaarden() {
  const isMobile = window.useIsMobile();
  const waarden = [
    {
      titel: "Vuur",
      sub: ["Passie", "Daadkracht", "Commitment"],
      body: "Wij hebben het vuur dat ons drijft om vol gas te gaan voor onze klanten, kandidaten en collega's. Onze passie, daadkracht en commitment maken ons gedreven om steeds het beste te leveren. Gas geven, doorpakken, winnen — altijd met enthousiasme voor wat we doen.",
      accent: "var(--orange)",
    },
    {
      titel: "Puur",
      sub: ["Karakter", "Echt", "Verbindend"],
      body: "Wij hebben karakter. We zijn echt en puur. Eerlijkheid staat centraal: wij zijn lekker normaal, recht-door-zee en direct. We zeggen waar het op staat en blijven respectvol. Zo zijn wij de verbindende factor tussen vakprofessionals en de bedrijven die we helpen groeien.",
      accent: "var(--green)",
    },
    {
      titel: "Vakmanschap",
      sub: ["Kennis", "Kunde", "Focus"],
      body: "Vakmanschap is wat we doen en wat we zijn. We streven altijd naar groei en verbetering — van onszelf, de mensen met wie we werken, en de wereld om ons heen. Met diepgaande kennis van de sector, een scherp begrip van opdrachtgevers en de werkvloer maken we elke match duurzaam en succesvol.",
      accent: "var(--blue)",
    },
  ];
  return (
    <section style={{ background: "var(--card)", borderTop: "1px solid var(--line)", borderBottom: "1px solid var(--line)", marginTop: isMobile ? "80px" : "120px", position: "relative", overflow: "hidden" }}>
      <div aria-hidden="true" style={{ position: "absolute", inset: 0, backgroundImage: "linear-gradient(to right, rgba(21,23,28,.04) 1px, transparent 1px), linear-gradient(to bottom, rgba(21,23,28,.04) 1px, transparent 1px)", backgroundSize: "20px 20px", pointerEvents: "none" }} />
      <div aria-hidden="true" style={{ position: "absolute", top: "-160px", right: "-160px", width: "440px", height: "440px", borderRadius: "50%", border: "1.5px solid var(--orange)", opacity: .10, pointerEvents: "none" }} />

      <div style={{ position: "relative", maxWidth: "1200px", margin: "0 auto", padding: isMobile ? "64px 20px" : "96px 40px" }}>
        <div style={{ marginBottom: "48px", maxWidth: "780px" }}>
          <div style={{ marginBottom: "16px" }}><Eyebrow>Drie kernwaarden</Eyebrow></div>
          <h2 style={{
            fontFamily: "var(--font-display)", fontWeight: 800,
            fontSize: isMobile ? "clamp(34px, 9vw, 48px)" : "clamp(40px, 4.8vw, 60px)",
            letterSpacing: "-.045em", lineHeight: ".98",
            color: "var(--ink)", margin: 0, textWrap: "balance",
          }}>
            "Wij doen wat we doen omdat we geloven<br/>in de kracht van <em style={{ fontStyle: "italic", fontWeight: 300 }}>vakmanschap</em>."
          </h2>
        </div>

        <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "repeat(3, 1fr)", gap: "16px" }}>
          {waarden.map((w) => (
            <article key={w.titel} style={{
              background: "#fff", border: "1px solid var(--line)", borderRadius: "var(--r)",
              padding: isMobile ? "28px 24px" : "32px 28px",
              position: "relative", overflow: "hidden",
            }}>
              <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: "4px", background: w.accent }} />
              <h3 style={{
                fontFamily: "var(--font-display)", fontWeight: 800,
                fontSize: "44px", letterSpacing: "-.04em", lineHeight: 1,
                textTransform: "uppercase", color: "var(--ink)", margin: "8px 0 6px",
              }}>
                {w.titel}
              </h3>
              <div style={{ display: "flex", gap: "6px", marginBottom: "16px", flexWrap: "wrap" }}>
                {w.sub.map((s, i) => (
                  <React.Fragment key={s}>
                    <span style={{ fontFamily: "var(--font-mono)", fontSize: "11px", fontWeight: 700, letterSpacing: ".06em", textTransform: "uppercase", color: w.accent }}>
                      {s}
                    </span>
                    {i < w.sub.length - 1 && <span style={{ color: "var(--subtle)" }}>·</span>}
                  </React.Fragment>
                ))}
              </div>
              <p style={{ fontSize: "15px", lineHeight: 1.6, color: "var(--muted)", margin: 0 }}>
                {w.body}
              </p>
            </article>
          ))}
        </div>
      </div>
    </section>
  );
}

